<script setup lang="ts">
import {computed,nextTick,onUnmounted,ref,watch} from 'vue';
import {AlertCircle,CheckCircle2,Database,LoaderCircle,Pencil,PlugZap,Search,ShieldCheck,Workflow,ChevronUp} from 'lucide-vue-next';
import BiCredentialForm from './BiCredentialForm.vue';
import BiSourceRelationships from './BiSourceRelationships.vue';
import {createRequestGuard} from '../lib/async-response';
type Item=Record<string,any>;
const props=defineProps<{tenant:string;tenantName:string;resource:Item;management?:Item|null;request:(path:string,method?:string,data?:unknown)=>Promise<any>}>();
const emit=defineEmits<{updated:[];saved:[resource:string];notice:[message:string]}>();
const section=ref<HTMLElement|null>(null);const lastAction=ref('');
const editing=ref(false);const busy=ref('');const report=ref<Item|null>(null);const error=ref('');const search=ref('');const schema=ref('');const guard=createRequestGuard();
const tables=computed<Item[]>(()=>report.value?.tables??[]);
const filtered=computed(()=>tables.value.filter(table=>(table.schema+'.'+table.name+' '+table.columns.map((column:Item)=>column.name).join(' ')).toLowerCase().includes(search.value.toLowerCase())));
async function inspect(action:'test'|'schema'|'relationships',filters?:{schema:string|null;search:string|null;offset:number}){
 if(busy.value)return;const current=guard.next();busy.value=action;lastAction.value=action;report.value=null;error.value='';search.value='';
 try{const result=await props.request(`/catalog/${props.tenant}/credentials/${props.resource.id}/inspect/${action}`,'POST',filters??(action!=='test'&&schema.value.trim()?{schema:schema.value.trim()}:{}));if(current())report.value=result;}
 catch(e){if(current())error.value=(e as Error).message;}finally{if(current())busy.value='';}
}
async function closeReport(){if(busy.value)return;guard.invalidate();report.value=null;error.value='';await nextTick();section.value?.querySelector<HTMLButtonElement>(`[data-inspection-action="${lastAction.value}"]`)?.focus({preventScroll:true});}
watch(()=>[props.tenant,props.resource.ref],()=>{guard.invalidate();report.value=null;error.value='';busy.value='';editing.value=false;schema.value='';});
onUnmounted(()=>guard.invalidate());
</script>
<template>
 <section ref="section" class="credential-actions" aria-label="Gerenciar conexão de dados">
  <BiCredentialForm v-if="editing" :tenant="tenant" :tenant-name="tenantName" :resource="resource" :request="request" @close="editing=false" @updated="emit('updated')" @notice="emit('notice',$event)" @saved="emit('saved',$event)"/>
  <template v-else><div class="credential-actions-heading"><ShieldCheck :size="18"/><div><h3>Gerenciar conexão</h3><p>Confira o acesso e a estrutura da fonte pelo agente do G-Analise.</p></div></div><div class="credential-action-buttons"><button v-if="management?.can_edit" class="secondary-button" :disabled="!!busy" @click="editing=true"><Pencil :size="15"/>Editar conexão</button><button class="primary-button" :disabled="!!busy" data-inspection-action="test" @click="inspect('test')"><LoaderCircle v-if="busy==='test'" :size="15" class="spin"/><PlugZap v-else :size="15"/>Testar conexão</button><button class="secondary-button" :disabled="!!busy" data-inspection-action="schema" @click="inspect('schema')"><LoaderCircle v-if="busy==='schema'" :size="15" class="spin"/><Database v-else :size="15"/>Ver tabelas e colunas</button><button class="secondary-button" :disabled="!!busy" data-inspection-action="relationships" @click="inspect('relationships')"><LoaderCircle v-if="busy==='relationships'" :size="15" class="spin"/><Workflow v-else :size="15"/>Ver relacionamentos</button></div>
   <p v-if="management?.message" class="credential-action-note">{{management.message}}</p><details class="credential-schema-filter"><summary>Filtrar por schema (opcional)</summary><label>Nome do schema<input v-model="schema" placeholder="Ex.: public ou dbo" :disabled="!!busy" maxlength="128"></label><p>Deixe em branco para consultar os ambientes disponíveis desta fonte.</p></details>
   <p v-if="busy" class="credential-action-note" role="status"><LoaderCircle :size="15" class="spin"/>Consultando o agente. Nenhuma carga de dados será iniciada.</p><p v-if="error" class="form-error" role="alert"><AlertCircle :size="16"/>{{error}}</p>
   <div v-if="report" class="credential-report-tools"><button type="button" class="text-button" :disabled="!!busy" @click="closeReport"><ChevronUp :size="14"/>Ocultar consulta</button></div>
   <div v-if="report" class="credential-report" :class="{confirmed:report.verified}" role="status"><CheckCircle2 v-if="report.verified" :size="20"/><AlertCircle v-else :size="20"/><div><strong>{{report.verified?(report.relationships?'Relacionamentos consultados':report.tables?'Estrutura consultada':'Conexão confirmada'):'Sem confirmação'}}</strong><p>{{report.message}}</p><small>Consultado em {{new Date(report.checked_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}} · Brasília</small></div></div>
   <BiSourceRelationships v-if="report?.verified&&report.relationships" :report="report" :schema="schema" :busy="!!busy" @query="inspect('relationships',$event)"/>
   <template v-if="report?.verified&&report.tables"><div class="credential-table-search"><Search :size="15"/><input v-model="search" aria-label="Buscar tabela ou coluna na conexão" placeholder="Buscar tabela ou coluna…"></div><p v-if="report.truncated" class="credential-action-note">Esta consulta está limitada. Use o filtro de schema para consultar uma parte menor da fonte.</p><p v-if="!filtered.length" class="credential-action-note">{{tables.length?'Nenhuma tabela corresponde à busca.':'A fonte retornou uma lista de tabelas vazia nesta consulta.'}}</p><details v-for="table in filtered" :key="table.schema+'.'+table.name" class="credential-source-table"><summary><Database :size="15"/><strong>{{table.name}}</strong><small>{{table.schema||'Schema não informado'}} · {{table.columns.length}} coluna(s)</small></summary><ul><li v-for="(column,index) in table.columns" :key="index"><span>{{column.name}}</span><small>{{column.type||'Tipo não informado'}}</small></li></ul></details></template>
  </template>
 </section>
</template>
<style scoped>
.credential-actions{margin-top:20px;border:1px solid #dce6f4;border-radius:10px;padding:18px;background:#f8fbff}.credential-actions-heading{display:flex;align-items:flex-start;gap:10px;color:#3e608d}.credential-actions-heading h3{font-size:13px;margin:0 0 6px}.credential-actions-heading p,.credential-action-note{font-size:12px;color:#6b7f9c;line-height:1.7}.credential-action-buttons{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}.credential-schema-filter{font-size:11px;color:#7185a0;margin:16px 0}.credential-schema-filter summary{cursor:pointer}.credential-schema-filter label{display:block;max-width:280px;margin:12px 0}.credential-schema-filter input{display:block;width:100%;margin-top:6px;background:white}.credential-schema-filter p{line-height:1.7}.credential-report-tools{display:flex;justify-content:flex-end;margin-top:14px}.credential-report-tools button{display:flex;align-items:center;gap:6px;font-size:11px;color:#426c9f}.credential-report{display:flex;gap:12px;padding:14px;border:1px solid #eddfc8;background:#fffaf2;color:#86602e;border-radius:8px;margin-top:15px}.credential-report>svg{flex-shrink:0}.credential-report.confirmed{color:#287253;border-color:#d4e8dd;background:#f1faf5}.credential-report strong{font-size:13px}.credential-report p{font-size:12px;line-height:1.7;margin:7px 0}.credential-report small{font-size:10px;color:#71869c}.credential-table-search{display:flex;gap:9px;align-items:center;border:1px solid #dfe7f3;background:white;border-radius:7px;padding:0 11px;margin:17px 0;color:#8ba0b9}.credential-table-search input{border:0;box-shadow:none;background:transparent;width:100%}.credential-source-table{border:1px solid #e1e8f2;border-radius:7px;margin-top:8px;background:#fff}.credential-source-table summary{display:flex;align-items:center;gap:9px;cursor:pointer;padding:12px;color:#4d6c94}.credential-source-table strong{font-size:12px}.credential-source-table summary small{font-size:10px;color:#8797ae;margin-left:auto}.credential-source-table ul{list-style:none;margin:0;padding:0 13px 10px}.credential-source-table li{display:flex;gap:15px;justify-content:space-between;padding:8px 0;border-top:1px solid #eef2f8;font-size:11px;color:#4a5f7d}.credential-source-table li small{font-size:10px;color:#8a9bb1}.credential-action-note svg{display:inline-block;vertical-align:middle;margin-right:6px}@media(max-width:600px){.credential-actions{padding:13px}.credential-action-buttons button{flex-grow:1}.credential-source-table summary{flex-wrap:wrap}.credential-source-table summary small{width:100%;margin-left:24px}}
</style>
